import re
from flask import g
import flask_tasks
from flask_babel import gettext

from .title_case import title_case

class TitleFormatter:
    def __init__(self, locale=None):
        self.locale = locale or g.locale

    def _get_localized_name(self, obj):
        return title_case(getattr(obj, f"name_{self.locale}"))

    def _format_distance(self, obj, name):
        if hasattr(obj, "distance") and obj.id != "all" and obj.distance > 0:
            return f"{name} {obj.distance}km"
        return name

    def _article(self, attr, article):
        if attr.article_pt:
            if attr.gender_pt == "m":
                if article == "em": new_article = "no"
                if article == "de": new_article = "do"
                if article == "para": new_article = "para o"
            elif attr.gender_pt == "f":
                if article == "em": new_article = "na"
                if article == "de": new_article = "da"
                if article == "para": new_article = "para a"
            if attr.plural_pt:
                new_article += "s"
            return new_article
        return article

    def format(self, title, attrs):
        if not isinstance(attrs, (list, tuple)):
            attrs = [attrs]

        conjunction = f" {gettext('and')} "
        if attrs[0].id in ("all", "sabra"):
            attr_type = "bra"
        else:
            attr_type = attrs[0].__class__.__name__.lower()

        names = [self._format_distance(a, self._get_localized_name(a)) for a in attrs]

        article_match = re.search(f"<{attr_type}_(\\w+)>", title)
        if article_match:
            title = title.replace(f" <{attr_type}>", "")
            title = title.replace(
                article_match.group(0),
                conjunction.join(
                    [
                        self._article(attrs[i], article_match.group(1)) + " " + names[i]
                        for i in range(len(names))
                    ]
                ),
            )
        else:
            title = title.replace(f"<{attr_type}>", conjunction.join(names))

        return title

def title_format(title, attr):
    formatter = TitleFormatter()
    return formatter.format(title, attr)

